import React, { useState } from "react";
import { Button } from "../../components/core/Button.jsx";
import { Eyebrow } from "../../components/core/Eyebrow.jsx";
import { Field } from "../../components/core/Field.jsx";

const FOCI = ["Growth", "Positioning", "Procurement", "Operations", "Not sure / something else"];
const FAQ = [
  ["What does a growth strategy consultant do for a consumer brand?", "I find the growth opportunities a brand can't see from the inside, then build the plan to capture them: assortment and merchandising strategy, retail and marketplace expansion, and the operational path to execute."],
  ["How do engagements work?", "Four ways: a 30-day Opportunity Mapping engagement, a 60+ day growth project, a 90+ day operational buildout, or a monthly advisory retainer. Every larger engagement starts with a Project Fit Call, not a contract."],
  ["Who do you work with?", "Consumer brands ready to grow, and the retailers and marketplaces that sell them. Past work spans outdoor, footwear, beauty, wellness, and Amazon-native brands."],
  ["Where are you based, and do you work remotely?", "Based in Salt Lake City, Utah, working with brands across the US. Most engagements run remotely, with on-site time where the work calls for it."],
];

export function ContactScreen() {
  const [sent, setSent] = useState(false);
  const [focus, setFocus] = useState([]);
  const toggle = (f) => setFocus((s) => s.includes(f) ? s.filter((x) => x !== f) : [...s, f]);

  return (
    <div>
      <section style={{ padding: "clamp(140px,16vh,220px) var(--mx) var(--section-y)", maxWidth: "840px" }}>
        <Eyebrow onDark>Contact</Eyebrow>
        <h1 style={{ fontFamily: "var(--font-display)", fontSize: "clamp(2.6rem,6vw,5rem)", lineHeight: 0.96, letterSpacing: "-0.01em", margin: "22px 0 18px", color: "var(--parchment)" }}>Let's build what's next.</h1>
        <p style={{ fontWeight: 300, fontSize: "var(--fs-lead)", lineHeight: 1.5, margin: 0, color: "var(--dusk-2)" }}>Tell me where you're trying to take the business and what's standing in the way.</p>

        <div style={{ marginTop: "48px", border: "1px solid var(--line-light)", padding: "clamp(24px,4vw,48px)", background: "var(--obsidian-2)" }}>
          {sent ? (
            <div style={{ textAlign: "center", padding: "20px 0" }}>
              <div style={{ width: "48px", height: "48px", background: "var(--violet)", color: "var(--parchment)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 18px", fontSize: "1.4rem" }}>&#10003;</div>
              <h3 style={{ fontFamily: "var(--font-display)", fontWeight: 400, fontSize: "1.6rem", margin: "0 0 10px", color: "var(--parchment)" }}>Message sent.</h3>
              <p style={{ fontWeight: 300, color: "var(--dusk-2)", margin: "0 auto", maxWidth: "44ch", lineHeight: 1.6 }}>Thank you for reaching out. Your message landed in my inbox and I'll reply within two business days.</p>
            </div>
          ) : (
            <>
              <h3 style={{ fontFamily: "var(--font-display)", fontWeight: 400, fontSize: "1.5rem", margin: "0 0 6px", color: "var(--parchment)" }}>Send a message</h3>
              <p style={{ fontWeight: 300, fontSize: "0.95rem", color: "var(--dusk-2)", margin: "0 0 30px" }}>Rather talk than type? <a href="#" style={{ color: "var(--violet-light)", textUnderlineOffset: "4px" }}>Book a 20-minute Project Fit Call</a> and skip the form.</p>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "24px", marginBottom: "24px" }}>
                <Field label="Full name" required placeholder="Your name" onDark />
                <Field label="Email address" required type="email" placeholder="you@company.com" onDark />
              </div>
              <div style={{ marginBottom: "24px" }}><Field label="Company name" placeholder="Company or brand" onDark /></div>
              <div style={{ marginBottom: "24px" }}>
                <span style={{ display: "block", fontFamily: "var(--font-sans)", fontWeight: 600, fontSize: "var(--fs-meta)", textTransform: "uppercase", letterSpacing: "0.16em", color: "var(--dusk-2)", marginBottom: "12px" }}>What can I help with?</span>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
                  {FOCI.map((f) => {
                    const on = focus.includes(f);
                    return <button key={f} onClick={() => toggle(f)} style={{ cursor: "pointer", fontFamily: "var(--font-sans)", fontSize: "0.85rem", fontWeight: on ? 600 : 400, padding: "9px 16px", borderRadius: "0", border: `1px solid ${on ? "var(--violet-light)" : "var(--line-light-strong)"}`, background: on ? "rgba(180,156,224,0.14)" : "transparent", color: on ? "var(--violet-light)" : "var(--parchment)", transition: "all var(--dur-fast) var(--ease-out)" }}>{f}</button>;
                  })}
                </div>
              </div>
              <div style={{ marginBottom: "30px" }}><Field label="What's prompting you to reach out?" required textarea placeholder="A sentence or two about your business and what you'd like to explore." onDark /></div>
              <Button variant="fill" onClick={() => setSent(true)}>Send a Message</Button>
              <p style={{ fontWeight: 300, fontSize: "0.85rem", color: "var(--dusk-2)", margin: "18px 0 0" }}>Prefer email? Write me directly at <a href="mailto:addie@opportunitydesigned.com" style={{ color: "var(--violet-light)" }}>addie@opportunitydesigned.com</a>.</p>
            </>
          )}
        </div>
      </section>

      <section style={{ padding: "0 var(--mx) var(--section-y)", maxWidth: "840px" }}>
        <Eyebrow onDark>Common questions</Eyebrow>
        <h2 style={{ fontFamily: "var(--font-display)", fontSize: "clamp(1.8rem,3vw,2.6rem)", margin: "14px 0 26px", color: "var(--parchment)" }}>Asked &amp; answered</h2>
        <div>
          {FAQ.map(([q, a], i) => (
            <div key={i} style={{ borderTop: "1px solid var(--line-light)", padding: "24px 0" }}>
              <h3 style={{ display: "flex", gap: "14px", fontFamily: "var(--font-sans)", fontWeight: 500, fontSize: "1.05rem", margin: "0 0 10px", color: "var(--parchment)" }}>
                <span style={{ fontFamily: "var(--font-display)", color: "var(--violet-light)", fontWeight: 400 }}>0{i + 1}</span>{q}
              </h3>
              <p style={{ fontWeight: 300, fontSize: "0.98rem", lineHeight: 1.65, margin: 0, paddingLeft: "28px", color: "var(--dusk-2)" }}>{a}</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

